import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-microsoft-nonprofit`,geoNote:!0,children:[(0,r.jsx)(`p`,{children:`Microsoft offers grants and discounts to eligible nonprofit organisations. Offers and eligibility are set by Microsoft, vary by country and can change, so always check the current details.`}),(0,r.jsx)(`p`,{children:`For Australian not-for-profits, these offers can make a real difference to the cost of email, file storage, collaboration and security. This guide explains what is typically available, who qualifies, how registration works, and what to plan for after you are approved. Pricing and offer details change from time to time, so treat this as an overview and confirm specifics on Microsoft's nonprofit website before you make decisions.`}),(0,r.jsx)(`h2`,{children:`Typical offers`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Microsoft 365 Business Basic`}),` granted free for up to 300 users. This covers web and mobile versions of Word, Excel and PowerPoint, Outlook email, Teams, SharePoint and OneDrive cloud storage.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Discounted Microsoft 365 Business Premium`}),` and other plans, such as Microsoft 365 E3 and E5, plus a lower-cost frontline plan.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`An annual Azure credit grant`}),` for eligible organisations that use Microsoft Azure cloud services.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Discounts on Copilot, Dynamics 365 and Power Platform`}),`, including nonprofit pricing on Microsoft 365 Copilot and some Dynamics 365 and Power Apps products.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Discounted security add-ons`}),`, such as Microsoft Defender, Purview and Intune, for organisations that need stronger protection.`]})]}),(0,r.jsx)(`h3`,{children:`What changed in 2025`}),(0,r.jsx)(`p`,{children:`From 1 July 2025, Microsoft retired its free Microsoft 365 Business Premium grant (previously up to 10 free licences) and the Office 365 E1 grant for nonprofits. Business Basic remains free for up to 300 users, and Business Premium is still available at a nonprofit discount. Organisations that relied on the free Premium licences had to move to a paid or different plan at renewal. Nonprofit subscriptions are now generally paid annually, so budget for a yearly payment rather than a monthly one.`}),(0,r.jsx)(`p`,{children:`If your organisation set up Microsoft 365 a few years ago, it's worth checking the admin centre to confirm which licences you hold now and when they renew.`}),(0,r.jsx)(`h2`,{children:`Who is eligible?`}),(0,r.jsx)(`p`,{children:`Generally, organisations with recognised nonprofit or charitable legal status in their country that meet Microsoft's criteria. They must operate on a not-for-profit basis, have a mission that benefits the community (for example social welfare, education, environment, culture or human rights), and agree to Microsoft's non-discrimination policy. Public libraries and public museums can also qualify.`}),(0,r.jsx)(`p`,{children:`Some organisation types are excluded. These include government agencies, schools, colleges and universities, professional and trade associations, sports organisations, and political, labour and fraternal groups. Education bodies usually have separate Microsoft programs, and health services should check the current criteria carefully. Individuals, volunteers and members are not eligible in their own right.`}),(0,r.jsx)(`h2`,{children:`How to register`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Gather your registration details (in Australia, your ACNC registration).`}),` Have your ABN, legal name, registered address and a contact email on your organisation domain ready. Make sure your ACNC listing is current, because verification draws on public information.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Register through Microsoft's nonprofit portal.`}),` `,`Go to Microsoft's Nonprofit Hub and either create a new Microsoft 365 tenant or sign in with your existing one. Registration must be done by an employee or authorised volunteer of the organisation, not by an outside IT provider.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Wait for verification.`}),` `,`Microsoft uses a third-party validation partner to check eligibility. Microsoft says this can take up to a few business days, though it may take longer if extra documents are requested.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Activate the grants and plans that suit each person.`}),` Once approved, offers appear in the Nonprofit Hub and the Microsoft 365 admin centre.`]})]}),(0,r.jsx)(`p`,{children:`Microsoft also asks organisations to confirm their eligibility periodically by agreeing to its donation rules, so keep your account details and contacts up to date.`}),(0,r.jsx)(`h2`,{children:`Choosing the right licence for each person`}),(0,r.jsx)(`p`,{children:`You don't need to give everyone the same plan. A practical approach is to mix licences by role:`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Business Basic`}),` for volunteers and staff who mainly use email, Teams and shared files in a browser.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Business Premium`}),` for people handling sensitive client, donor or financial information, or who need the desktop Office apps and device management.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Frontline plans`}),` for shift workers who need limited access on a shared or mobile device.`]})]}),(0,r.jsxs)(`p`,{children:[`For a deeper comparison of what each plan includes, see `,(0,r.jsx)(e,{to:`/blog-microsoft-365-plans-compared`,children:`Microsoft 365 Business Basic vs Standard vs Premium`}),`.`]}),(0,r.jsx)(`h2`,{children:`Common mistakes to avoid`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Using personal accounts.`}),` Free consumer email makes it hard to control access when people leave. Use accounts on your own domain.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Skipping security settings.`}),` Free licences still need multi-factor authentication and sensible sharing settings. Not-for-profits hold personal information and are attractive targets for scammers.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Leaving old licences in place.`}),` Remove licences when staff or volunteers leave, so you are not paying for or exposing unused accounts.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Not planning the migration.`}),` Moving email and files from another system needs a plan so nothing is lost.`]})]}),(0,r.jsxs)(`p`,{children:[`If you hold personal information, it's also worth reading our guide to the `,(0,r.jsx)(e,{to:`/blog-essential-eight-guide`,children:`ASD Essential Eight`}),` for practical security priorities.`]}),(0,r.jsx)(`h2`,{children:`Quick checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`ACNC registration and ABN details current.`}),(0,r.jsx)(`li`,{children:`Organisation domain and admin contact ready.`}),(0,r.jsx)(`li`,{children:`Registered through the Microsoft Nonprofit Hub.`}),(0,r.jsx)(`li`,{children:`Licences assigned by role, not one size for all.`}),(0,r.jsx)(`li`,{children:`Multi-factor authentication turned on for everyone.`}),(0,r.jsx)(`li`,{children:`Renewal dates and annual costs noted in your budget.`})]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Is Microsoft 365 really free for not-for-profits?`}),(0,r.jsx)(`p`,{children:`Microsoft 365 Business Basic is granted free for up to 300 users for eligible organisations. Other plans, including Business Premium, are discounted rather than free.`}),(0,r.jsx)(`h3`,{children:`Can our IT provider register on our behalf?`}),(0,r.jsx)(`p`,{children:`Microsoft requires an employee or authorised volunteer to complete registration. An IT partner can help you prepare, check your details and set everything up once you are approved.`}),(0,r.jsx)(`h3`,{children:`What if our application is declined?`}),(0,r.jsx)(`p`,{children:`Check that your legal status and public records match what you entered, then contact Microsoft's nonprofit support through the Nonprofit Hub. Some organisation types are simply not eligible, in which case standard business licensing applies.`}),(0,r.jsx)(`h3`,{children:`We already use Microsoft 365. Can we switch to nonprofit offers?`}),(0,r.jsx)(`p`,{children:`Yes. You can register your existing tenant for nonprofit status, then change licences in the admin centre at a sensible point, usually around renewal.`}),(0,r.jsxs)(`p`,{children:[`We can help with eligibility, registration and setup. See `,(0,r.jsx)(e,{to:`/microsoft#nonprofit`,children:`Microsoft for Nonprofits`}),`, or read about our `,(0,r.jsx)(e,{to:`/microsoft-licensing`,children:`Microsoft licensing`}),` for Australian organisations.`]})]})}export{i as default};